/**
 * The accessible FAQ is React's FAQ (react-frontend/public/locales/<locale>/
 * public.json -> faq.categories), generated by scripts/build-faq.js. It had five
 * questions of its own while React had twenty in five groups (29 Oct 2026).
 */

const express = require('express');

// The community's own questions come from Laravel; never call it from a test.
jest.mock('../src/lib/api', () => {
  const actual = jest.requireActual('../src/lib/api');
  return { ...actual, getHelpFaqs: jest.fn().mockResolvedValue({ data: [] }) };
});
const api = require('../src/lib/api');
const nunjucks = require('nunjucks');
const path = require('path');
const request = require('supertest');
const { createChoiceTranslator, createTranslator } = require('../src/lib/localization');
const { registerTemplateFilters } = require('../src/lib/template-filters');
const { build, isStale } = require('../scripts/build-faq');
const publicInfoRoutes = require('../src/routes/public-info');

const VIEWS = path.join(__dirname, '..', 'src', 'views');
const GOVUK = path.join(__dirname, '..', 'node_modules', 'govuk-frontend', 'dist');

function buildApp(locale = 'en') {
  const app = express();
  const env = nunjucks.configure([VIEWS, GOVUK], { autoescape: true, express: app, watch: false });
  registerTemplateFilters(env);
  app.set('view engine', 'njk');
  app.set('views', VIEWS);
  app.use((req, res, next) => {
    req.accessibleRouting = { mode: 'shared', tenantSlug: 'acme', tenant: { id: 2, slug: 'acme', name: 'Acme Timebank' }, prefix: '' };
    Object.assign(res.locals, {
      urlFor: (value) => String(value || '/'),
      serviceName: 'Project NEXUS',
      tenantName: 'Acme Timebank',
      alphaNavItems: [],
      alphaFooterColumns: [],
      csrfToken: 'test-csrf',
      htmlLang: locale,
      htmlDirection: locale === 'ar' ? 'rtl' : 'ltr',
      locale,
      t: createTranslator(locale),
      tc: createChoiceTranslator(locale)
    });
    next();
  }, publicInfoRoutes);
  return app;
}

describe('accessible FAQ follows React', () => {
  it('the generated copy matches React\'s locale files', () => {
    expect(isStale(build().content)).toBe(false);
  });

  it('shows all twenty questions in their five groups, with lists and links', async () => {
    const res = await request(buildApp()).get('/faq');
    expect(res.status).toBe(200);
    expect((res.text.match(/class="govuk-accordion__section-button"/g) || []).length).toBe(20);
    expect((res.text.match(/<h2 class="govuk-heading-l govuk-!-margin-top-7" id="faq-/g) || []).length).toBe(5);
    expect(res.text).toContain('href="/wallet"');
    expect(res.text).toContain('govuk-list--bullet');
  });

  it('is translated', async () => {
    const res = await request(buildApp('ga')).get('/faq');
    expect(res.status).toBe(200);
    expect(res.text).toContain('An féidir liom mo chreidmheasanna a bhronnadh?');
  });
  // AWID focus group, Oct 2026: "Can we customise the text in places like FAQ?"
  it('shows the community own questions above the standard ones', async () => {
    api.getHelpFaqs.mockResolvedValueOnce({ data: [{ category: 'Joining', faqs: [{ id: 7, question: 'How do I join the market?', answer: '<p>Write to the coordinators.</p>' }] }] });

    const res = await request(buildApp()).get('/faq');

    expect(res.status).toBe(200);
    expect(res.text).toContain('How do I join the market?');
    expect(res.text).toContain('Write to the coordinators.');
    expect(res.text.indexOf('How do I join the market?')).toBeLessThan(res.text.indexOf('id="faq-getting_started"'));
  });

  it('still shows the standard questions when the community questions cannot be read', async () => {
    api.getHelpFaqs.mockRejectedValueOnce(new Error('down'));

    const res = await request(buildApp()).get('/faq');

    expect(res.status).toBe(200);
    expect((res.text.match(/class="govuk-accordion__section-button"/g) || []).length).toBe(20);
  });
});
